CREATE COLUMN TABLE "TEST_AP"."OMTC" ("DocEntry" INTEGER CS_INT NOT NULL , "MatchID" SMALLINT CS_INT DEFAULT 1 NOT NULL , "Round" SMALLINT CS_INT NOT NULL , "MtcRule" SMALLINT CS_INT DEFAULT 0, "MtcAlias" NVARCHAR(50), "Differnce" INTEGER CS_INT DEFAULT 0, "DiffAmnt" DECIMAL(21,6) CS_FIXED, "RuleIndex" SMALLINT CS_INT NOT NULL , PRIMARY KEY ("DocEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OMTC_MATCH_TYPE" ON "TEST_AP"."OMTC" ( "MatchID" ASC, "Round" ASC, "RuleIndex" ASC )